function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(65001);
var T0=Date.now();
var P=10,BUD=300;
var projs=[];for(var i=0;i<P;i++){var cost=10+Math.floor(R()*90);projs.push({cost:cost,roi:+(cost*(0.5+R()*2)).toFixed(1)});}
var byDens=projs.slice().sort(function(a,b){return (b.roi/b.cost)-(a.roi/a.cost);});
var spent=0,roi=0,n=0;byDens.forEach(function(p){if(spent+p.cost<=BUD){spent+=p.cost;roi+=p.roi;n++;}});
var spent2=0,roi2=0;projs.forEach(function(p){if(spent2+p.cost<=BUD){spent2+=p.cost;roi2+=p.roi;}});
console.log(JSON.stringify({id:"JAH-APX65-000001",ok:true,metrics:{projects:P,budget:BUD,funded:n,spent:spent,total_roi:+roi.toFixed(1),baseline_roi:+roi2.toFixed(1),gain_vs_baseline_pct:+((roi/Math.max(roi2,1)-1)*100).toFixed(1)},ms:Date.now()-T0}));

